    BR = (0xE6, 0x00, 0x12)
    def logo(grow, under):
        """ロゴ（800×240、背景は透明）。grow＝輪郭を太らせる量（px）。under＝完全に透明な所に入っている（見えない）色"""
        k = 4; W, H = 800 * k, 240 * k; g = grow * k
